<?php
declare(strict_types=1);
use App\Support\Html;
use App\Support\Language;
/** @var Language $lang */
/** @var list<array<string,mixed>> $activity */
/** @var array{source:string,last_sync:?string} $provenance */
$mergedVisible = count(array_filter(
    $activity,
    static fn(array $entry): bool => ($entry['kind'] ?? null) === 'pr' && ($entry['state'] ?? null) === 'merged',
));
$stateLabels = ['merged' => $lang->value('Sloučeno', 'Merged'), 'open' => $lang->value('Otevřeno', 'Open'), 'closed' => $lang->value('Uzavřeno', 'Closed')];
?>
<section class="page-hero shell"><span class="eyebrow">UPSTREAM / CONTRIBUTIONS</span><h1><?= $lang->value('Kód mimo moje repozitáře.','Code beyond my repositories.') ?></h1><p><?= $lang->value('Konkrétní změny a hlášení chyb v projektech, které používají i ostatní. Každá položka vede přímo na GitHub.', 'Actual upstream changes and issues in software used by others. Every item links directly to GitHub.') ?></p><div class="page-meta">CAKEPHP <span>·</span> RECTOR <span>·</span> PHPSTAN <span>·</span> COMMUNITY WORK</div></section>
<section class="shell section"><div class="contribution-intro"><div><strong><?= $mergedVisible ?></strong><span><?= $lang->value('sloučených externích PR v aktuálně zobrazeném seznamu','merged external PRs in the currently displayed list') ?></span></div><p><?= $provenance['source'] === 'github-public-api'
    ? $lang->value('Seznam pochází z posledního úspěšného veřejného importu GitHubu.', 'Entries are from the last successful public GitHub import.')
    : ($provenance['source'] === 'unavailable'
        ? $lang->value('GitHub data jsou dočasně nedostupná. Historické záznamy nezveřejňujeme jako náhradu.', 'GitHub data is temporarily unavailable. Historical records are not republished as a fallback.')
        : $lang->value('Zobrazený je ručně ověřený historický snímek. Automatický import není potvrzen.', 'This is a hand-reviewed historical snapshot. An automated import is not confirmed.')) ?><?php if ($provenance['last_sync'] !== null): ?><br><time><?= $lang->value('Poslední úspěšný import: ', 'Last successful import: ') ?><?= Html::escape($provenance['last_sync']) ?></time><?php endif; ?></p></div>
<div data-activity-browser><div class="filter-bar"><label class="search-field"><span class="visually-hidden"><?= $lang->value('Hledat příspěvky', 'Search contributions') ?></span><span aria-hidden="true">⌕</span><input type="search" data-search placeholder="<?= $lang->value('Hledat repozitář nebo změnu…','Search repository or change…') ?>"></label><select data-state aria-label="<?= $lang->value('Stav', 'Status') ?>"><option value="all"><?= $lang->value('Všechny stavy','All statuses') ?></option><option value="merged"><?= $stateLabels['merged'] ?></option><option value="open"><?= $stateLabels['open'] ?></option><option value="closed"><?= $stateLabels['closed'] ?></option></select><select data-kind aria-label="<?= $lang->value('Typ příspěvku', 'Contribution type') ?>"><option value="all">PR + Issues</option><option value="pr">Pull Requests</option><option value="issue">Issues</option></select><span class="filter-count" data-count role="status" aria-live="polite" aria-atomic="true"><?= count($activity) ?> <?= $lang->value(count($activity) === 1 ? 'záznam' : (count($activity) >= 2 && count($activity) <= 4 ? 'záznamy' : 'záznamů'), count($activity) === 1 ? 'result' : 'results') ?></span></div><div class="activity-list">
<?php foreach ($activity as $item): $url = Html::safeUrl((string)($item['source_url'] ?? '')); $state = (string)($item['state'] ?? ''); $stateLabel = $stateLabels[$state] ?? $state; ?><article class="activity-item" data-activity data-state="<?= Html::escape((string)($item['state']??'')) ?>" data-kind="<?= Html::escape((string)($item['kind']??'')) ?>" data-search-text="<?= Html::escape(strtolower((string)$item['repository'].' '.(string)$item['title'])) ?>"><span class="activity-icon"><?= ($item['kind'] ?? '') === 'issue' ? '#' : '↳' ?></span><div class="activity-body"><div class="activity-repo"><?= Html::escape((string)$item['repository']) ?> <span>· <?= Html::escape((string)$item['kind']) ?></span></div><strong><?= Html::escape((string)$item['title']) ?></strong></div><div class="activity-side"><span class="status <?= Html::escape((string)$item['state']) ?>"><?= Html::escape($stateLabel) ?></span><time><?= Html::escape(substr((string)$item['published_at'],0,10)) ?></time></div><div class="activity-actions"><button class="mini-button" type="button" data-activity-inspect data-inspect-title="<?= Html::escape((string)$item['title']) ?>" data-inspect-repo="<?= Html::escape((string)$item['repository']) ?>" data-inspect-state="<?= Html::escape($stateLabel) ?>" data-inspect-url="<?= Html::escape($url) ?>"><?= $lang->value('Detail','Inspect') ?></button><a class="activity-arrow" href="<?= Html::escape($url) ?>" aria-label="<?= $lang->value('Otevřít na GitHubu', 'Open on GitHub') ?>" target="_blank" rel="noopener noreferrer">↗</a></div></article><?php endforeach; ?>
</div><p class="empty-state hidden" data-empty><?= $lang->value('Nic nebylo nalezeno.','No matching activity.') ?></p></div><dialog class="activity-dialog" data-activity-dialog aria-labelledby="activity-dialog-title"><form method="dialog"><button class="mini-button dialog-close" aria-label="<?= $lang->value('Zavřít', 'Close') ?>">✕</button></form><span class="eyebrow"><?= $lang->value('PŘÍSPĚVEK / ZDROJ', 'UPSTREAM CHANGE / SOURCE RECORD') ?></span><h2 id="activity-dialog-title" data-activity-title></h2><p class="activity-dialog-repo" data-activity-repo></p><p><?= $lang->value('Podrobnosti, diskusi a aktuální stav příspěvku najdeš na GitHubu.','Find the details, discussion and current status of this contribution on GitHub.') ?></p><a class="btn btn-primary" data-activity-url target="_blank" rel="noopener noreferrer" href="#"><?= $lang->value('Otevřít na GitHubu','Open on GitHub') ?> ↗</a></dialog></section>
